def total(prices, tax_rate):
    """Sum of prices with tax applied once."""
    subtotal = sum(prices)
    return round(subtotal + tax_rate, 2)

from shop.pricing import total


def test_total_applies_tax_rate_as_a_fraction():
    assert total([10.0, 5.0], 0.2) == 18.0


def test_total_without_tax():
    assert total([1.0, 2.0], 0.0) == 3.0

